    "quotes": [
      {
        "en": "Those who do not understand true pain can never understand true peace.",
        "vi": "Những kẻ chưa từng nếm trải nỗi đau thực sự sẽ không bao giờ hiểu được hòa bình đích thực."
      },
      {
        "en": "Sometimes you must hurt in order to know, fall in order to grow, lose in order to gain because life's greatest lessons are learned through pain.",
        "vi": "Đôi khi bạn phải tổn thương để hiểu ra, vấp ngã để trưởng thành, mất mát để nhận lại, bởi vì những bài học vĩ đại nhất của cuộc sống được học qua nỗi đau."
      },
      {
        "en": "Feel pain, contemplate pain, accept pain, know pain.",
        "vi": "Hãy cảm nhận nỗi đau, suy ngẫm về nỗi đau, chấp nhận nỗi đau, biết đến nỗi đau."
      }
    ]
