        "en": "People keep asking if I'm back, and I haven't really had an answer, but yeah, I'm thinking I'm back.",
        "vi": "Mọi người liên tục hỏi tôi đã quay lại chưa, và tôi chưa thực sự có câu trả lời, nhưng ừ, tôi nghĩ là tôi đã quay lại."
