        "en": "Those who break the rules are trash, but those who abandon their comrades are worse than trash.",
        "vi": "Những kẻ phá vỡ luật lệ là rác rưởi, nhưng những kẻ bỏ rơi đồng đội của mình thì còn tệ hơn cả rác rưởi."
